-- Minimal isolated contract fixture. No real accounts, data or credentials.
create role anon;
create role authenticated;
create schema auth;
create schema private;
grant usage on schema private to authenticated;
create function auth.uid() returns uuid language sql stable as $$ select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb) $$;
create table public.profiles(id uuid primary key, role text not null, status text not null, full_name text);
create table public.groups(id uuid primary key default gen_random_uuid());
create table public.coach_group_assignments(coach_id uuid references profiles(id), group_id uuid references groups(id), is_active boolean default true);
create function private.is_active_user() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=(select auth.uid()) and status='active') $$;
create function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select coalesce((select auth.jwt()->>'aal'),'aal1')='aal2' and exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin' and status='active') $$;
create function private.has_group(g uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.coach_group_assignments a join public.profiles p on p.id=a.coach_id where a.coach_id=(select auth.uid()) and a.group_id=g and a.is_active and p.status='active') $$;
create table public.events(id uuid primary key default gen_random_uuid(), group_id uuid references groups(id), event_type text default 'training', status text default 'scheduled', start_at timestamptz, ends_at timestamptz, venue_id uuid, venue_part text default 'whole');
create function private.event_in_my_group(e uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.events where id=e and private.has_group(group_id)) $$;
create table public.players(id uuid primary key default gen_random_uuid(), group_id uuid references groups(id), is_active boolean default true);
create type public.attendance_status as enum('present','absent');
create table public.attendance_sessions(id uuid primary key default gen_random_uuid(), event_id uuid unique references events(id), completed_at timestamptz, completed_by uuid references profiles(id) on delete set null, idempotency_key uuid, client_created_at timestamptz, server_version integer default 1, updated_at timestamptz default now());
create table public.attendance_records(id uuid primary key default gen_random_uuid(), session_id uuid references attendance_sessions(id) on delete cascade, player_id uuid references players(id), status public.attendance_status, note text, actor_id uuid, unique(session_id,player_id));
create table public.player_behavior_cards(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), group_id uuid references groups(id), coach_id uuid references profiles(id) on delete set null, coach_name_snapshot text not null default 'Synthetic coach', event_id uuid references events(id), occurred_on date, month date, reason text default 'late', comment text, is_voided boolean default false, voided_at timestamptz, voided_by uuid, void_reason text, updated_at timestamptz default now());
create unique index behavior_card_one_active_per_event on public.player_behavior_cards(event_id, player_id) where not is_voided;
alter table public.attendance_sessions enable row level security;
alter table public.attendance_records enable row level security;
alter table public.player_behavior_cards enable row level security;
create policy session_read on public.attendance_sessions for select to authenticated using(private.is_admin() or private.event_in_my_group(event_id));
create policy attendance_read on public.attendance_records for select to authenticated using(exists(select 1 from public.attendance_sessions s where s.id=session_id));
create policy card_read on public.player_behavior_cards for select to authenticated using(private.is_admin() or private.has_group(group_id));
create policy card_insert on public.player_behavior_cards for insert to authenticated with check(private.has_group(group_id) and coach_id=auth.uid() and not is_voided);
create policy card_void on public.player_behavior_cards for update to authenticated using(private.has_group(group_id)) with check(private.has_group(group_id) and is_voided and voided_by=auth.uid());
grant select on public.events, public.players, public.profiles, public.attendance_sessions, public.attendance_records, public.player_behavior_cards to authenticated;
grant insert, update on public.player_behavior_cards to authenticated;
